def build_model(config: TaskConfig) -> nn.Module:
    """LSTM encoder following Weiss/Goldberg/Yahav 2018 counter recipe."""

    class LSTMEncoder(nn.Module):
        def __init__(self, cfg: TaskConfig):
            super().__init__()
            self.embed = nn.Embedding(cfg.vocab_size, cfg.hidden_dim, padding_idx=cfg.pad_id)
            self.rnn = nn.LSTM(
                input_size=cfg.hidden_dim,
                hidden_size=cfg.hidden_dim,
                num_layers=2,
                batch_first=True,
            )
            self.norm = nn.LayerNorm(cfg.hidden_dim)

        def forward(self, tokens: torch.Tensor, lengths: torch.Tensor) -> torch.Tensor:
            h = self.embed(tokens)
            out, _ = self.rnn(h)
            last_idx = (lengths - 1).clamp(min=0).view(-1, 1, 1).expand(-1, 1, out.size(-1))
            last = out.gather(1, last_idx).squeeze(1)
            return self.norm(last)

    return LSTMEncoder(config)

def build_model(config: TaskConfig) -> DyckModel:
    """Two-layer LSTM language model (Hewitt et al. EMNLP 2020 baseline)."""

    class LSTMModel(DyckModel):
        def __init__(self, vocab: int, hidden: int, num_layers: int):
            super().__init__()
            self.embed = nn.Embedding(vocab, hidden)
            self.rnn = nn.LSTM(hidden, hidden, num_layers=num_layers, batch_first=True)
            self.head = nn.Linear(hidden, vocab)

        def forward(self, input_ids: torch.Tensor) -> torch.Tensor:
            h = self.embed(input_ids)
            h, _ = self.rnn(h)
            return self.head(h)

    return LSTMModel(
        vocab=vocab_size(config.k),
        hidden=config.hidden_dim,
        num_layers=2,
    )

class FlipFlopModel(nn.Module):
    """1-layer LSTM. Perfect skyline per Liu et al. (NeurIPS 2023) R2."""

    def __init__(self, vocab_size: int = VOCAB_SIZE, max_len: int = 1024):
        super().__init__()
        hidden = 128
        self.embed = nn.Embedding(vocab_size, hidden)
        self.rnn = nn.LSTM(
            input_size=hidden,
            hidden_size=hidden,
            num_layers=1,
            batch_first=True,
        )
        self.head = nn.Linear(hidden, vocab_size, bias=False)

    def forward(self, tokens: torch.Tensor) -> torch.Tensor:
        h = self.embed(tokens)
        out, _ = self.rnn(h)
        return self.head(out)


def build_model(config: TaskConfig) -> nn.Module:
    """Construct the LSTM FFLM (1-layer, hidden=128, ~133K params)."""
    return FlipFlopModel(
        vocab_size=VOCAB_SIZE,
        max_len=max(config.train_len, config.eval_long_len),
    )

